Here is a complete, modular, and production-ready implementation of the Autonomous Traffic Light Control System in C#. 

The system is split into three isolated, decoupled modules using reactive event streams (via `IObservable<T>` / `IObserver<T>` patterns or clear interfaces) to ensure high cohesion, low coupling, and testability.

### C# Implementation

```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

// ============================================================================
// SHARED DOMAIN MODELS & CONTRACTS
// ============================================================================
namespace TrafficControlSystem.Domain
{
    public enum LaneId { NorthBound, SouthBound, EastBound, WestBound }

    public enum SignalState { Red, Yellow, Green }

    public record VehicleDetectedEvent(LaneId Lane, int VehicleCountDelta, DateTime Timestamp);

    public record IntersectionState(Dictionary<LaneId, int> QueueLengths);

    public record TimingDecision(LaneId TargetLane, TimeSpan GreenDuration);

    public record SignalCommand(LaneId Lane, SignalState State);
}

// ============================================================================
// MODULE 1: Intersection Vehicle Sensor Ingester
// ============================================================================
namespace TrafficControlSystem.Sensors
{
    using TrafficControlSystem.Domain;

    public interface ISensorIngester
    {
        IObservable<IntersectionState> StateStream { get; }
        void IngestSensorData(VehicleDetectedEvent sensorEvent);
        Dictionary<LaneId, int> GetCurrentQueues();
    }

    /// <summary>
    /// Tracks and maintains real-time queue lengths for all intersection lanes.
    /// Thread-safe for concurrent sensor inputs.
    /// </summary>
    public class VehicleSensorIngester : ISensorIngester
    {
        private readonly ConcurrentDictionary<LaneId, int> _laneQueues;
        private readonly Queue<IntersectionState> _stateHistory = new();

        // Using an event-driven observable pattern for downstream subscribers
        private readonly System.Reactive.Subjects.Subject<IntersectionState> _stateSubject = new();
        public IObservable<IntersectionState> StateStream => _stateSubject;

        public VehicleSensorIngester()
        {
            _laneQueues = new ConcurrentDictionary<LaneId, int>(
                Enum.GetValues<LaneId>().ToDictionary(lane => lane, _ => 0)
            );
        }

        public void IngestSensorData(VehicleDetectedEvent sensorEvent)
        {
            _laneQueues.AddOrUpdate(sensorEvent.Lane, 
                addValue: Math.Max(0, sensorEvent.VehicleCountDelta), 
                updateValueFactory: (lane, currentCount) => Math.Max(0, currentCount + sensorEvent.VehicleCountDelta)
            );

            var currentState = new IntersectionState(new Dictionary<LaneId, int>(_laneQueues));
            _stateSubject.OnNext(currentState);
        }

        public Dictionary<LaneId, int> GetCurrentQueues()
        {
            return new Dictionary<LaneId, int>(_laneQueues);
        }
    }
}

// ============================================================================
// MODULE 2: Adaptive Timing Optimization Engine
// ============================================================================
namespace TrafficControlSystem.Optimization
{
    using TrafficControlSystem.Domain;

    public interface ITimingEngine
    {
        TimingDecision CalculateNextPhase(IntersectionState state);
    }

    /// <summary>
    /// Computes optimal green light durations using queue-length heuristics.
    /// </summary>
    public class AdaptiveTimingEngine : ITimingEngine
    {
        private readonly TimeSpan _minGreenTime = TimeSpan.FromSeconds(5);
        private readonly TimeSpan _maxGreenTime = TimeSpan.FromSeconds(45);
        private readonly TimeSpan _timePerVehicle = TimeSpan.FromSeconds(2); // Heuristic: 2s per car

        public TimingDecision CalculateNextPhase(IntersectionState state)
        {
            if (state.QueueLengths == null || !state.QueueLengths.Any())
            {
                throw new ArgumentException("Invalid intersection state provided.");
            }

            // Heuristic: Select the lane with the longest queue
            var criticalLane = state.QueueLengths.OrderByDescending(kvp => kvp.Value).First();

            // Calculate dynamic duration: Base time + (Vehicles * TimePerVehicle)
            double calculatedSeconds = _minGreenTime.TotalSeconds + (criticalLane.Value * _timePerVehicle.TotalSeconds);

            // Clamp within safety boundaries
            var boundedDuration = TimeSpan.FromSeconds(
                Math.Clamp(calculatedSeconds, _minGreenTime.TotalSeconds, _maxGreenTime.TotalSeconds)
            );

            return new TimingDecision(criticalLane.Key, boundedDuration);
        }
    }
}

// ============================================================================
// MODULE 3: Hardware Signal Controller
// ============================================================================
namespace TrafficControlSystem.Hardware
{
    using TrafficControlSystem.Domain;

    public interface IHardwareController
    {
        Task DispatchSignalChangeAsync(SignalCommand command, CancellationToken cancellationToken = default);
        SignalState GetCurrentState(LaneId lane);
    }

    /// <summary>
    /// Dispatches state changes to physical or simulated traffic light hardware safely,
    /// enforcing mandatory Interlocking (All-Red clearance phases).
    /// </summary>
    public class HardwareSignalController : IHardwareController
    {
        private readonly ConcurrentDictionary<LaneId, SignalState> _hardwareStates;
        private readonly TimeSpan _interlockClearanceTime = TimeSpan.FromSeconds(2); // All-Red safety interval

        public HardwareSignalController()
        {
            _hardwareStates = new ConcurrentDictionary<LaneId, SignalState>(
                Enum.GetValues<LaneId>().ToDictionary(lane => lane, _ => SignalState.Red)
            );
        }

        public async Task DispatchSignalChangeAsync(SignalCommand command, CancellationToken cancellationToken = default)
        {
            var currentLaneState = _hardwareStates[command.Lane];

            if (currentLaneState == command.State) return;

            // Enforce Yellow transition if moving from Green to Red
            if (currentLaneState == SignalState.Green && command.State == SignalState.Red)
            {
                await TransitionToStateAsync(command.Lane, SignalState.Yellow, TimeSpan.FromSeconds(3), cancellationToken);
                await Task.Delay(_interlockClearanceTime, cancellationToken); // Safety All-Red clearance
            }

            await TransitionToStateAsync(command.Lane, command.State, TimeSpan.Zero, cancellationToken);
        }

        public SignalState GetCurrentState(LaneId lane) => _hardwareStates[lane];

        private Task TransitionToStateAsync(LaneId lane, SignalState state, TimeSpan dwellTime, CancellationToken token)
        {
            _hardwareStates[lane] = state;
            Console.WriteLine($"[HARDWARE DISPATCH] Lane {lane} transitioned to -> {state}");

            if (dwellTime > TimeSpan.Zero)
            {
                return Task.Delay(dwellTime, token);
            }
            return Task.CompletedTask;
        }
    }
}

// ============================================================================
// SYSTEM ORCHESTRATOR (Composition Root)
// ============================================================================
namespace TrafficControlSystem
{
    using TrafficControlSystem.Domain;
    using TrafficControlSystem.Sensors;
    using TrafficControlSystem.Optimization;
    using TrafficControlSystem.Hardware;

    public class TrafficControlOrchestrator
    {
        private readonly ISensorIngester _sensorIngester;
        private readonly ITimingEngine _timingEngine;
        private readonly IHardwareController _hardwareController;
        private IDisposable _subscription;

        public TrafficControlOrchestrator(
            ISensorIngester sensorIngester, 
            ITimingEngine timingEngine, 
            IHardwareController hardwareController)
        {
            _sensorIngester = sensorIngester;
            _timingEngine = timingEngine;
            _hardwareController = hardwareController;
        }

        public void Start()
        {
            // Wire Module 1's state stream to trigger Module 2 & 3 updates reactively
            _subscription = _sensorIngester.StateStream.Subscribe(async state =>
            {
                // 1. Optimize timing based on current queues
                TimingDecision decision = _timingEngine.CalculateNextPhase(state);
                Console.WriteLine($"[OPTIMIZATION ENGINE] Selected Lane {decision.TargetLane} for {decision.GreenDuration.TotalSeconds}s green.");

                // 2. Dispatch hardware changes (Make target lane Green, others Red)
                foreach (LaneId lane in Enum.GetValues<LaneId>())
                {
                    var targetState = (lane == decision.TargetLane) ? SignalState.Green : SignalState.Red;
                    await _hardwareController.DispatchSignalChangeAsync(new SignalCommand(lane, targetState));
                }
            });
        }

        public void Stop() => _subscription?.Dispose();
    }

    // ============================================================================
    // PROGRAM ENTRYPOINT (Simulation Example)
    // ============================================================================
    public class Program
    {
        public static async Task Main(string[] args)
        {
            // 1. Instantiate Isolated Modules
            var sensorIngester = new VehicleSensorIngester();
            var timingEngine = new AdaptiveTimingEngine();
            var hardwareController = new HardwareSignalController();

            // 2. Compose System via Orchestrator
            var orchestrator = new TrafficControlOrchestrator(sensorIngester, timingEngine, hardwareController);
            orchestrator.Start();

            Console.WriteLine("--- Autonomous Traffic Light Control System Initialized ---");

            // 3. Simulate Sensor Ingestion (Vehicles arriving at lanes)
            sensorIngester.IngestSensorData(new VehicleDetectedEvent(LaneId.NorthBound, 5, DateTime.UtcNow));
            sensorIngester.IngestSensorData(new VehicleDetectedEvent(LaneId.SouthBound, 12, DateTime.UtcNow)); // Heuristic target
            sensorIngester.IngestSensorData(new VehicleDetectedEvent(LaneId.EastBound, 2, DateTime.UtcNow));
            sensorIngester.IngestSensorData(new VehicleDetectedEvent(LaneId.WestBound, 3, DateTime.UtcNow));

            await Task.Delay(2000); // Let async hardware transitions settle

            Console.WriteLine("\n--- Simulating Queue Shift (EastBound congestion) ---");
            sensorIngester.IngestSensorData(new VehicleDetectedEvent(LaneId.EastBound, 20, DateTime.UtcNow)); // New target

            await Task.Delay(2000);

            orchestrator.Stop();
            Console.WriteLine("--- System Shutdown ---");
        }
    }
}
```

### Key Architectural Highlights:
1. **Strict Module Isolation**: 
   - **Module 1 (`VehicleSensorIngester`)** only cares about counting incoming/outgoing vehicles via thread-safe collections (`ConcurrentDictionary`) and broadcasting state changes.
   - **Module 2 (`AdaptiveTimingEngine`)** is a pure functional heuristic calculation engine; it has no side-effects or hardware awareness.
   - **Module 3 (`HardwareSignalController`)** encapsulates hardware states, safely managing critical safety protocols like **Yellow clearance intervals** and **All-Red interlocks**.
2. **Reactive Flow**: The orchestrator ties modules together via an asynchronous observable pattern (`IObservable<IntersectionState>`), meaning the pipeline automatically reacts downstream the moment sensor counts update.
